wid.addMethod(CtNewMethod.make("""
public static String skillVal(String[] parts, String label) {
  if (parts == null || label == null) return "-";
  String want = label.trim();
  if (want.length() == 0) return "-";
  for (int i = 0; i < parts.length; i++) {
    String p = parts[i];
    if (p == null) continue;
    int c = p.lastIndexOf(':');
    if (c <= 0) continue;
    if (!p.substring(0, c).trim().equalsIgnoreCase(want)) continue;
    long v = lnum(p.substring(c + 1), -1L);
    return v < 0L ? "-" : String.valueOf(v);
  }
  return "-";
}""", wid))
