# face, so the plain font fits too); a word longer than a row is split by letters; only text beyond max rows ends in "..." on the last row
FXM(wid, """
public static String[] qWrap(String s, int room1, int roomN, int fs, int max) {
  if (s == null) s = "";
  if (room1 < 1 || roomN < 1) return new String[] { "" };
  if (max < 2 || textW(s, fs, true) <= room1) return new String[] { fitText(s, room1, fs, true) };
  java.util.ArrayList out = new java.util.ArrayList();
  String rest = s.trim();
  while (rest.length() > 0 && out.size() < max - 1) {
    int room = out.size() == 0 ? room1 : roomN;
    if (textW(rest, fs, true) <= room) break;
    int cut = -1;
    int i = rest.indexOf(' ');
    while (i > 0 && textW(rest.substring(0, i), fs, true) <= room) { cut = i; i = rest.indexOf(' ', i + 1); }
    String line;
    if (cut > 0) { line = rest.substring(0, cut); rest = rest.substring(cut + 1).trim(); }
    else {
      int n = 1;
      while (n < rest.length() && textW(rest.substring(0, n + 1), fs, true) <= room) n++;
      line = rest.substring(0, n); rest = rest.substring(n).trim();
    }
    out.add(line.trim());
  }
  if (rest.length() > 0 || out.size() == 0) out.add(fitText(rest, out.size() == 0 ? room1 : roomN, fs, true));
  String[] r = new String[out.size()];
  for (int k = 0; k < r.length; k++) r[k] = (String) out.get(k);
  return r;
}""")
