# 0.3.4: exact inverse of screenPosH for the layout's current anchor (same h); the top-left is clamped so the box stays on screen
wid.addMethod(CtNewMethod.make(f"""
public static void setTopLeftWH({PKG}.WLayout l, int x, int y, int w, int h) {{
  if (x > 1920 - w) x = 1920 - w;
  if (x < 0) x = 0;
  if (y > 1080 - h) y = 1080 - h;
  if (y < 0) y = 0;
  String a = l.anchor;
  if (a.equals("tl") || a.equals("l") || a.equals("bl")) l.dx = x;
  else if (a.equals("tr") || a.equals("r") || a.equals("br")) l.dx = 1920 - w - x;
  else l.dx = x - (960 - w / 2);
  if (a.equals("tl") || a.equals("t") || a.equals("tr")) l.dy = y;
  else if (a.equals("bl") || a.equals("b") || a.equals("br")) l.dy = 1080 - h - y;
  else l.dy = y - (540 - h / 2);
}}""", wid))
wid.addMethod(CtNewMethod.make(f"""
public static void setTopLeftH({PKG}.WLayout l, int x, int y, int h) {{
  setTopLeftWH(l, x, y, l.bw * l.scale / 100, h);
}}""", wid))
wid.addMethod(CtNewMethod.make(f"""
public static void clampToScreen({PKG}.WLayout l) {{
  if (l.mm != null) l.scale = {PKG}.MmCfg.snapScale(l.scale);
  if (l.fixed) l.scale = 100;
  int h = hMax(l);
  int[] p = screenPosH(l, h);
  setTopLeftH(l, p[0], p[1], h);
}}""", wid))
# put the widget's top-left at (x, y) and anchor it to the nearest screen corner (judged by the centre of the w x h box)
wid.addMethod(CtNewMethod.make(f"""
public static void cornerAtWH({PKG}.WLayout l, int x, int y, int w, int h) {{
  if (x > 1920 - w) x = 1920 - w;
  if (x < 0) x = 0;
  if (y > 1080 - h) y = 1080 - h;
  if (y < 0) y = 0;
  boolean left = x + w / 2 < 960; boolean top = y + h / 2 < 540;
  l.anchor = top ? (left ? "tl" : "tr") : (left ? "bl" : "br");
  setTopLeftWH(l, x, y, w, h);
}}""", wid))
wid.addMethod(CtNewMethod.make(f"""
public static void cornerAtH({PKG}.WLayout l, int x, int y, int h) {{
  cornerAtWH(l, x, y, l.bw * l.scale / 100, h);
}}""", wid))
# 0.3.4 canvas grid: 32 x 18 cells of 40 canvas px = 60 screen px; a widget's handle belongs in the cell under its centre
wid.addMethod(CtNewMethod.make(f"""
public static int cellOfWH({PKG}.WLayout l, int w, int h) {{
  int[] p = screenPosWH(l, w, h);
  int cx = p[0] + w / 2; int cy = p[1] + h / 2;
  int col = cx / 60; if (col < 0) col = 0; if (col > 31) col = 31;
  int row = cy / 60; if (row < 0) row = 0; if (row > 17) row = 17;
  return row * 32 + col;
}}""", wid))
wid.addMethod(CtNewMethod.make(f"""
public static int cellOfH({PKG}.WLayout l, int h) {{
  return cellOfWH(l, l.bw * l.scale / 100, h);
}}""", wid))
# a drag from cell `from` to cell `to` moves the widget by that distance (keeps sub-cell offsets), nearest corner anchor re-picked
wid.addMethod(CtNewMethod.make(f"""
public static void moveByCellsWH({PKG}.WLayout l, int from, int to, int w, int h) {{
  int[] p = screenPosWH(l, w, h);
  int mx = (to % 32 - from % 32) * 60; int my = (to / 32 - from / 32) * 60;
  cornerAtWH(l, p[0] + mx, p[1] + my, w, h);
}}""", wid))
wid.addMethod(CtNewMethod.make(f"""
public static void moveByCellsH({PKG}.WLayout l, int from, int to, int h) {{
  moveByCellsWH(l, from, to, l.bw * l.scale / 100, h);
}}""", wid))
# 0.3.9 Settings "Snap to": the pressed point itself becomes the anchor, 8 px from the screen edge on an edge axis and 0 (the true
