# the importCode rules: trim, strip ONE pair of surrounding " or ' (34 / 39), ":" -> ","
hcfg.addMethod(CtNewMethod.make("""
public static String unquote(String code) {
  String c = code == null ? "" : code.trim();
  if (c.length() >= 2) {
    char q = c.charAt(0);
    if ((q == 34 || q == 39) && c.charAt(c.length() - 1) == q) c = c.substring(1, c.length() - 1).trim();
  }
  return c.replace(':', ',');
}""", hcfg))
