# ================= 0.3.16 Widgets.mmPlace: the minimap's first free spot (Skyy 2026-10-06: it covered the top-right widgets) =========
# r = boxes (x, y, w, h at 1080p, 4 ints each); a box hits when it comes closer than the gap
wid.addMethod(CtNewMethod.make(f"""
public static boolean mmHit(int[] r, int n, int x, int y, int w, int h) {{
  for (int i = 0; i < n; i++) {{
    int bx = r[4 * i]; int by = r[4 * i + 1]; int bw = r[4 * i + 2]; int bh = r[4 * i + 3];
    if (x < bx + bw + 4 && bx < x + w + 4 && y < by + bh + 4 && by < y + h + 4) return true;
  }}
  return false;
}}""", wid))
# only the built-in spot of a minimap the player never placed (no line in their file - LayoutStore.get) and the server default does not
# place: tr anchor candidates x 8 / just left of a box, y 40 / 8 / just under a box; right half, on screen, no shown widget's maximum box
# within the gap; the smallest 2 x (dx - 8) + (dy - 8) wins (the right edge first; ties: higher up). true = moved
wid.addMethod(CtNewMethod.make(f"""
public static boolean mmPlace(java.util.Map m) {{
  {PKG}.WLayout w = ({PKG}.WLayout) m.get("Minimap");
  if (w == null) return false;
  {PKG}.WLayout d = def("Minimap");
  if (!d.anchor.equals(w.anchor) || w.dx != d.dx || w.dy != d.dy) return false;
  try {{ java.util.HashMap dm = {PKG}.HudCfg.layoutMap(); if (dm != null && dm.get("Minimap") != null) return false; }} catch (Throwable t) {{ }}
  int S = w.bw * w.scale / 100;
  int n = 0;
  int[] r = new int[4 * IDS.length];
  for (int i = 0; i < IDS.length; i++) {{
    if ("Minimap".equals(IDS[i])) continue;
    {PKG}.WLayout o = ({PKG}.WLayout) m.get(IDS[i]);
    if (o == null || !o.en) continue;
    int ow = o.bw * o.scale / 100;
    int oh = hMax(o);
    int[] p = screenPosWH(o, ow, oh);
    r[4 * n] = p[0]; r[4 * n + 1] = p[1]; r[4 * n + 2] = ow; r[4 * n + 3] = oh;
    n = n + 1;
  }}
  if (!mmHit(r, n, 1920 - S - w.dx, w.dy, S, S)) return false;
  int[] cx = new int[n + 1];
  int[] cy = new int[n + 2];
  cx[0] = 8; cy[0] = d.dy; cy[1] = 8;
  for (int i = 0; i < n; i++) {{ cx[i + 1] = 1920 - r[4 * i] + 6; cy[i + 2] = r[4 * i + 1] + r[4 * i + 3] + 6; }}
  int best = -1; int bdx = 0; int bdy = 0;
  for (int i = 0; i < cx.length; i++) {{
    int dx = cx[i];
    if (dx < 8 || 1920 - S - dx < 960) continue;
    for (int j = 0; j < cy.length; j++) {{
      int dy = cy[j];
      if (dy < 8 || dy + S > 1080 - 8) continue;
      if (mmHit(r, n, 1920 - S - dx, dy, S, S)) continue;
      int sc = 2 * (dx - 8) + (dy - 8);
      if (best < 0 || sc < best || (sc == best && dy < bdy)) {{ best = sc; bdx = dx; bdy = dy; }}
    }}
  }}
  if (best < 0) return false;
  w.dx = bdx;
  w.dy = bdy;
  clampToScreen(w);
  return true;
}}""", wid))

# 0.3.20 Widgets.feedPlace: a player whose saved file has no Feed line (everyone before 0.3.20) and whose server default does not place it
# gets the built-in spot bl 8,488 - unless it comes within 4 px of a shown widget's maximum box or the estimated vanilla chat (8, 600,
# 560 x 360; Layout-Spec.md section 1, an ESTIMATE): then the first free spot on the bl anchor (x 8 or 6 px right of a box; y 488, 6 px
# above a box or 6 px under one; on screen, the left half), the one nearest 8,488 first. true = moved. Saved lines are never moved.
FXM(wid, """
public static boolean feedPlace(java.util.Map m) {
  @PKG@.WLayout w = (@PKG@.WLayout) m.get("Feed");
  if (w == null || !w.en) return false;
  @PKG@.WLayout d = def("Feed");
  if (!d.anchor.equals(w.anchor) || w.dx != d.dx || w.dy != d.dy || w.scale != d.scale) return false;
  try { java.util.HashMap dm = @PKG@.HudCfg.layoutMap(); if (dm != null && dm.get("Feed") != null) return false; } catch (Throwable t) { }
  int fw = w.bw * w.scale / 100;
  int fh = w.bh * w.scale / 100;
  int n = 0;
  int[] r = new int[4 * (IDS.length + 1)];
  for (int i = 0; i < IDS.length; i++) {
    if ("Feed".equals(IDS[i]) || "Seasons".equals(IDS[i])) continue;
    @PKG@.WLayout o = (@PKG@.WLayout) m.get(IDS[i]);
    if (o == null || !o.en) continue;
    int ow = o.bw * o.scale / 100;
    int oh = hMax(o);
    int[] p = screenPosWH(o, ow, oh);
    r[4 * n] = p[0]; r[4 * n + 1] = p[1]; r[4 * n + 2] = ow; r[4 * n + 3] = oh;
    n = n + 1;
  }
  r[4 * n] = 8; r[4 * n + 1] = 600; r[4 * n + 2] = 560; r[4 * n + 3] = 360;
  n = n + 1;
  if (!mmHit(r, n, w.dx, 1080 - fh - w.dy, fw, fh)) return false;
  int[] cx = new int[n + 1];
  cx[0] = 8;
  for (int i = 0; i < n; i++) cx[i + 1] = r[4 * i] + r[4 * i + 2] + 6;
  int[] cy = new int[2 * n + 1];
  cy[0] = d.dy;
  for (int i = 0; i < n; i++) { cy[2 * i + 1] = 1080 - r[4 * i + 1] + 6; cy[2 * i + 2] = 1080 - (r[4 * i + 1] + r[4 * i + 3] + 6) - fh; }
  int best = -1; int bdx = 0; int bdy = 0;
  for (int i = 0; i < cx.length; i++) {
    int dx = cx[i];
    if (dx < 8 || dx + fw > 960) continue;
    for (int j = 0; j < cy.length; j++) {
      int dy = cy[j];
      if (dy < 8 || 1080 - fh - dy < 8) continue;
      if (mmHit(r, n, dx, 1080 - fh - dy, fw, fh)) continue;
      int sc = Math.abs(dy - d.dy) + (dx - 8);
      if (best < 0 || sc < best || (sc == best && Math.abs(dy - d.dy) < Math.abs(bdy - d.dy))) { best = sc; bdx = dx; bdy = dy; }
    }
  }
  if (best < 0) return false;
  w.dx = bdx;
  w.dy = bdy;
  clampToScreen(w);
  return true;
}""")

