lst.addMethod(CtNewMethod.make(f"""
public static java.util.Map get(java.util.UUID u) {{
  java.util.Map m = (java.util.Map) CACHE.get(u);
  if (m != null) return m;
  m = new java.util.concurrent.ConcurrentHashMap();
  String[] ids = {PKG}.Widgets.IDS;
  boolean mmf = false;
  boolean fdf = false;      // 0.3.20: the file has a Feed line
  boolean qdf = false;      // 0.3.21: the file has a Quest line
  try {{
    java.nio.file.Path f = DIR.resolve(u.toString() + ".properties");
    if (java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) {{
      java.util.Properties p = new java.util.Properties();
      java.io.InputStream in = java.nio.file.Files.newInputStream(f, new java.nio.file.OpenOption[0]);
      try {{ p.load(in); }} finally {{ in.close(); }}
      for (int i = 0; i < ids.length; i++) {{
        String v = p.getProperty(ids[i]);
        if (v != null && "Minimap".equals(ids[i])) mmf = true;
        if (v != null && "Feed".equals(ids[i])) fdf = true;
        if (v != null && "Quest".equals(ids[i])) qdf = true;
        {PKG}.WLayout d = {PKG}.Widgets.start(ids[i]);
        m.put(ids[i], v == null ? d : {PKG}.WLayout.parse(v, d));
      }}
    }}
  }} catch (Throwable t) {{ }}
  for (int i = 0; i < ids.length; i++) if (!m.containsKey(ids[i])) m.put(ids[i], {PKG}.Widgets.start(ids[i]));
  for (int i = 0; i < ids.length; i++) {{
    {PKG}.WLayout w = ({PKG}.WLayout) m.get(ids[i]);
    if (w == null) continue;
    {PKG}.Widgets.clampToScreen(w);
  }}
  // 0.3.16: a minimap the player never placed takes the first free spot (a COPY: Widgets.start may hand out the shared default)
  if (!mmf) {{
    try {{
      {PKG}.WLayout mw = ({PKG}.WLayout) m.get("Minimap");
      if (mw != null) {{
        {PKG}.WLayout cp = {PKG}.WLayout.parse(mw.ser(), mw);
        if (cp != null && cp != mw) {{ m.put("Minimap", cp); if (!{PKG}.Widgets.mmPlace(m)) m.put("Minimap", mw); }}
      }}
    }} catch (Throwable t) {{ }}
  }}
  // 0.3.20: a feed the player never placed takes the first free spot when the built-in one touches their widgets (a COPY, as the minimap)
  if (!fdf) {{
    try {{
      {PKG}.WLayout fw = ({PKG}.WLayout) m.get("Feed");
      if (fw != null) {{
        {PKG}.WLayout fc = {PKG}.WLayout.parse(fw.ser(), fw);
        if (fc != null && fc != fw) {{ m.put("Feed", fc); if (!{PKG}.Widgets.feedPlace(m)) m.put("Feed", fw); }}
      }}
    }} catch (Throwable t) {{ }}
  }}
  // 0.3.21: a quest widget the player never placed takes the first free spot when the built-in one touches their widgets (a COPY)
  if (!qdf) {{
    try {{
      {PKG}.WLayout qw = ({PKG}.WLayout) m.get("Quest");
      if (qw != null) {{
        {PKG}.WLayout qc = {PKG}.WLayout.parse(qw.ser(), qw);
        if (qc != null && qc != qw) {{ m.put("Quest", qc); if (!{PKG}.Widgets.questPlace(m)) m.put("Quest", qw); }}
      }}
    }} catch (Throwable t) {{ }}
  }}
  java.util.Map prev = (java.util.Map) CACHE.putIfAbsent(u, m);
  return prev != null ? prev : m;
}}""", lst))
lst.addMethod(CtNewMethod.make("""
public static void atomicWrite(java.nio.file.Path f, byte[] data) throws java.io.IOException {
  java.nio.file.Files.createDirectories(f.getParent(), new java.nio.file.attribute.FileAttribute[0]);
  java.nio.file.Path tmp = f.resolveSibling(f.getFileName().toString() + ".tmp");
  java.io.FileOutputStream out = new java.io.FileOutputStream(tmp.toFile());
  try {
    out.write(data);
    out.flush();
    out.getFD().sync();
  } finally { out.close(); }
  java.io.IOException last = null;
  for (int i = 0; i < 5; i++) {
    try {
      java.nio.file.Files.move(tmp, f, new java.nio.file.CopyOption[] { java.nio.file.StandardCopyOption.ATOMIC_MOVE, java.nio.file.StandardCopyOption.REPLACE_EXISTING });
      return;
    } catch (java.nio.file.AtomicMoveNotSupportedException e) {
      java.nio.file.Files.move(tmp, f, new java.nio.file.CopyOption[] { java.nio.file.StandardCopyOption.REPLACE_EXISTING });
      return;
    } catch (java.nio.file.FileSystemException e) {
      last = e;
    }
    try { Thread.sleep(20L); } catch (InterruptedException ie) { }
  }
  throw last;
}""", lst))
# ================= 0.3.19 HudThreads: SkyyHud's own single daemon thread "SkyyHud-Tick" =================
# EXEC = a ScheduledThreadPoolExecutor of one thread (the 1 s tick, layout writes, the attach delay - never HytaleServer.SCHEDULED_EXECUTOR,
# the engine's one shared scheduler thread). An instance is the ThreadFactory (no path) or one layout write (path + bytes).
hthr.addInterface(pool.get("java.util.concurrent.ThreadFactory"))
hthr.addInterface(pool.get("java.lang.Runnable"))
hthr.addField(CtField.make("public static volatile java.util.concurrent.ScheduledExecutorService EXEC;", hthr))
hthr.addField(CtField.make("public static final java.util.concurrent.atomic.AtomicLong WRITES = new java.util.concurrent.atomic.AtomicLong();", hthr))
hthr.addField(CtField.make("public java.nio.file.Path path;", hthr))
hthr.addField(CtField.make("public byte[] data;", hthr))
hthr.addConstructor(CtNewConstructor.make("public HudThreads() { this.path = null; this.data = null; }", hthr))
hthr.addConstructor(CtNewConstructor.make("public HudThreads(java.nio.file.Path p, byte[] d) { this.path = p; this.data = d; }", hthr))
hthr.addMethod(CtNewMethod.make("""
public Thread newThread(Runnable r) {
  Thread t = new Thread(r, "SkyyHud-Tick");
  t.setDaemon(true);
  return t;
}""", hthr))
