lst.addMethod(CtNewMethod.make(f"""
public static int importCode(java.util.UUID u, String code) {{
  java.util.Map m = get(u);
  int n = 0;
  String c = code == null ? "" : code.trim();
  if (c.length() >= 2 && ((c.charAt(0) == '"' && c.charAt(c.length() - 1) == '"') || (c.charAt(0) == '\\'' && c.charAt(c.length() - 1) == '\\''))) c = c.substring(1, c.length() - 1).trim();
  c = c.replace(':', ',');
  String[] parts = c.split(";");
  for (int i = 0; i < parts.length; i++) {{
    int eq = parts[i].indexOf('=');
    if (eq <= 0) continue;
    String id = parts[i].substring(0, eq).trim();
    if (!m.containsKey(id)) continue;
    {PKG}.WLayout l = {PKG}.WLayout.parse(parts[i].substring(eq + 1), null);
    if (l == null) continue;
    {PKG}.WLayout dd = {PKG}.Widgets.def(id);
    l.bw = dd.bw; l.bh = dd.bh;
    l.ldef = dd.ldef; if (dd.ldef < 0) l.lines = -1; else if (l.lines <= 0) l.lines = dd.ldef;
    if (dd.mm == null) l.mm = null; else if (l.mm == null) l.mm = "";
    l.fixed = dd.fixed;
    {PKG}.Widgets.clampToScreen(l);
    m.put(id, l); n++;
  }}
  if (n > 0) save(u);
  return n;
}}""", lst))
