# ---------------------------------------------------------------- HudMig34 (0.3.34, bug 4): the one-time minimap speed update of config.properties
# PROJECT-RULES 4 (the reviewed SkyyMobs 0.1.11 MobMig11 pattern): only a key whose LAST entry is a one-line entry holding exactly its old
# default moves (value text only: key, separator and CR stay); an admin's own value is kept (INFO); no line = nothing (the code default is
# 0.3.34's); a verified History copy first; one config-changes.log line per moved key (row key, Undo in Server Setup -> Changes); the
# run-once marker on its own line above the first such entry and the comment lines directly on top of it (else above line 0); every other
# byte and the line endings kept; a java.util.Properties check. HudCfg.load runs it after writeDefaults, BEFORE the file is read.
HM34_ROWS = [("mm.tilesPerTick", "hud.mm.tilesPerTick", "24", "6", "map pieces shrunk per 0.25 s - 24 sent bursts of up to 96 pictures a second (lag)")]


