# HudCfg.load: returns the INFO lines joined by \n ("" = nothing done: no file, the marker already there, or a failure - WARN, file
# untouched, retried at the next start)
_hm34(r"""
public static synchronized String run(java.nio.file.Path f) {
  if (f == null) return "";
  try {
    if (!java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) return "";
    byte[] old = java.nio.file.Files.readAllBytes(f);
    Object[] r = update(new String(old, "ISO-8859-1"));
    if (r == null) return "";
    byte[] data = ((String) r[0]).getBytes("ISO-8859-1");
    String[] rows = (String[]) r[3];
    if (!sameAfter(old, data, rows)) {
      @PKG@.HudCfg.warn("config.properties NOT updated for the 0.3.34 minimap speed: the update would change more than its line (the file is used as it is; the next start tries again)");
      return "";
    }
    int fi = fileIdx();
    if (fi < 0) return "";
    kit(f.toAbsolutePath().getParent());
    @PKG@.CfgHist.snapshot(fi, old, @PKG@.CfgHist.stamp(), WHO, WHAT);
    if (!saved(fi, old)) {
      @PKG@.HudCfg.warn("config.properties NOT updated for the 0.3.34 minimap speed: the old file could not be kept in " + @PKG@.CfgHist.DIR + " (the file is used as it is; the next start tries again)");
      return "";
    }
    @PKG@.CfgRows.atomicWrite(f, data);
    for (int i = 0; i + 3 < rows.length; i += 4) @PKG@.CfgLog.enqueue(logLine(rows[i], rows[i + 1], rows[i + 2]));
    if (rows.length > 0) @PKG@.CfgLog.flush();
    String chg = (String) r[1];
    String[] kept = (String[]) r[2];
    String msg = null;
    if (chg.length() > 0) msg = "config.properties updated for 0.3.34 (minimap pictures sent slower, no bursts): " + chg + " (the old file is in config-history; Server Setup -> Changes can undo it)";
    else msg = "config.properties: mm.tilesPerTick did not hold its old default 24 - no value changed (0.3.34 update marker added; the old file is in config-history)";
    @PKG@.HudCfg.info(msg);
    StringBuilder all = new StringBuilder(msg);
    for (int i = 0; i < kept.length; i++) { @PKG@.HudCfg.info(kept[i]); all.append('\n').append(kept[i]); }
    return all.toString();
  } catch (Throwable t) {
    @PKG@.HudCfg.warn("could not update config.properties for the 0.3.34 minimap speed (the file is used as it is): " + t);
    return "";
  }
}""")

