MMM(mmmain, r"""
public static void rebuildCheck(@PKG@.MmSess s, @WLD@ w) {
  try {
    if (!s.rbDone && SESS.get(s.uuid) == s && s.pr != null && s.pr.isValid()) {
      @REF@ ref = s.pr.getReference();
      if (ref == null) rebuildSend(s, "between worlds (no page open)");
      else {
        @ST@ st = ref.isValid() ? ref.getStore() : null;
        @WLD@ here = null;
        try { here = st == null ? null : ((@ES@) st.getExternalData()).getWorld(); } catch (Throwable t) { here = null; }
        if (st == null || here != w) s.rbNext = System.currentTimeMillis() + 250L;
        else {
          @PLA@ p = (@PLA@) st.getComponent(ref, @PLA@.getComponentType());
          Object cp = null;
          if (p != null && p.getPageManager() != null) cp = p.getPageManager().getCustomPage();
          if (cp == null) rebuildSend(s, s.rbWaitLogged ? "after the open page closed" : "(no page open)");
          else {
            s.rbNext = System.currentTimeMillis() + 500L;
            if (!s.rbWaitLogged) {
              s.rbWaitLogged = true;
              info("minimap: " + s.who + " has a page open (" + cp.getClass().getSimpleName() + ") - the one picture rebuild waits until it is closed");
            }
          }
        }
      }
    }
  } catch (Throwable t) { s.rbNext = System.currentTimeMillis() + 1000L; err("the picture rebuild check", t); }
  s.rbAsk = false;
}""")
# the minimap thread: no entity in a world yet (connect: no page can exist) = write it now; else ONE check on the player's world thread
MMM(mmmain, r"""
public static void rebuild(@PKG@.MmSess s, long now) {
  if (s.rbAsk && now - s.rbAskAt > 3000L) s.rbAsk = false;     // review fix: the world stopped before the check ran - ask again
  if (s.rbDone || s.rbAsk || now < s.rbNext || s.pr == null) return;
  @REF@ ref = null;
  try { ref = s.pr.getReference(); } catch (Throwable t) { ref = null; }
  if (ref == null) { rebuildSend(s, "at connect, before the player is in a world"); return; }
  @WLD@ w = null;
  try { java.util.UUID wu = s.pr.getWorldUuid(); w = wu == null ? null : @UNI@.get().getWorld(wu); } catch (Throwable t) { w = null; }
  if (w == null) { s.rbNext = now + 250L; return; }
  s.rbAsk = true;
  s.rbAskAt = now;
  try { w.execute(new @PKG@.MmRebuild(s, w)); }
  catch (Throwable t) { s.rbAsk = false; s.rbNext = now + 1000L; err("reaching the world thread for the picture rebuild", t); }
}""")
# the 14 masks (7 sizes x round / square) + 16 arrows + the "not yet" picture go ONCE per connection, then ONE rebuild (critic C14)
