# the document for a geometry, built once on THIS thread and cached (critic C10): MmHud.show() hands it over on the world thread
MMM(mmmain, r"""
public static @UCB@ doc(@PKG@.MmSess s, String anc) {
  String k = anc + "|" + s.S + "|" + s.C + "|" + s.t + "|" + s.w + "|" + s.dp + "|" + s.ap + "|" + s.ring + "|" + s.maskRel + "|" + s.ringPath + "|" + s.dark + "|" + s.arrows[0] + "|" + s.kindPath[0];
  Object o = DOCS.get(k);
  if (o != null) return (@UCB@) o;
  @UCB@ b = new @UCB@();
  String pth = s.dark;
  int gl = groupPos(16.0, 0, s.C, s.t);
  int gt = gl;
  b.appendInline((String) null, "Group #SkyyMmRoot { Anchor: (Full: 0); }");
  b.appendInline("#SkyyMmRoot", "Group #SkyyMmBox { Anchor: " + (anc) + "; }");
  b.appendInline("#SkyyMmBox", "Group #SkyyMmClip { Anchor: (Left: " + (s.rw) + ", Top: " + (s.rw) + ", Width: " + (s.C) + ", Height: " + (s.C) + "); MaskTexturePath: \"" + (s.maskRel) + "\"; Background: #000000(0.3); }");
  b.appendInline("#SkyyMmClip", "Group #SkyyMmGrid { Anchor: (Left: " + (gl) + ", Top: " + (gt) + ", Width: " + (s.span * s.t) + ", Height: " + (s.span * s.t) + "); }");
  for (int i = 0; i < s.w * s.w; i++) b.appendInline("#SkyyMmGrid", "AssetImage #SkyyMmT" + (i) + " { Anchor: (Left: " + ((i % s.w) * s.t) + ", Top: " + ((i / s.w) * s.t) + ", Width: " + (s.t) + ", Height: " + (s.t) + "); AssetPath: \"" + (pth) + "\"; }");
  pth = s.kindPath[0];
  for (int i = 0; i < @QMK@; i++) b.appendInline("#SkyyMmGrid", "AssetImage #SkyyMmMk" + (i) + " { Anchor: (Left: -4000, Top: -4000, Width: " + (s.dp) + ", Height: " + (s.dp) + "); AssetPath: \"" + (pth) + "\"; }");
  pth = s.partyPath;
  for (int i = 0; i < @QPT@; i++) b.appendInline("#SkyyMmGrid", "AssetImage #SkyyMmPt" + (i) + " { Anchor: (Left: -4000, Top: -4000, Width: " + (s.dp) + ", Height: " + (s.dp) + "); AssetPath: \"" + (pth) + "\"; }");
  pth = s.arrows[0];
  b.appendInline("#SkyyMmBox", "AssetImage #SkyyMmArrow { Anchor: (Left: " + ((s.S - s.ap) / 2) + ", Top: " + ((s.S - s.ap) / 2) + ", Width: " + (s.ap) + ", Height: " + (s.ap) + "); AssetPath: \"" + (pth) + "\"; }");
  if (s.ring == 1) { pth = s.ringPath; b.appendInline("#SkyyMmBox", "AssetImage #SkyyMmRing { Anchor: (Left: 0, Top: 0, Width: " + (s.S) + ", Height: " + (s.S) + "); AssetPath: \"" + (pth) + "\"; }"); }
  DOCS.put(k, b);
  if (DOCS.size() > 64) { java.util.Iterator it = DOCS.keySet().iterator(); it.next(); it.remove(); }
  return b;
}""")
