# 0.3.30: a failure that means the world thread no longer takes tasks (shutdown / world removed): an IllegalThreadStateException
# anywhere in the cause chain (the engine wraps it in a SkipSentryException) or its "not accepting tasks" text
MMM(mmmain, r"""
public static boolean stopped(Throwable t) {
  Throwable c = t;
  for (int i = 0; i < 8 && c != null; i++) {
    if (c instanceof IllegalThreadStateException) return true;
    String m = c.getMessage();
    if (m != null && m.indexOf("not accepting tasks") >= 0) return true;
    c = c.getCause();
  }
  return false;
}""")
MMM(mmmain, r"""
public static void detach(@PKG@.MmSess s, String why) {
  @PKG@.MmHud h = s.hud;
  s.hud = null;
  s.posKnown = false;
  if (h == null) return;
  h.ended = true;
  if (s.world != null && s.pr != null && s.store != null) {
    try { s.world.execute(new @PKG@.MmDetach(s.pr, s.store, h)); } catch (Throwable t) { if (!stopped(t)) err("reaching the world thread to remove the minimap", t); }   // 0.3.30: a stopped world = nothing to remove
  }
}""")
