# THE TAP (the thread that writes the packet): the reference only - one volatile read when no minimap runs, never a lock, never a throw
MMM(mmmain, r"""
public static void tap(@PR@ pr, Object p) {
  if (TAPS == 0 || pr == null || p == null) return;
  boolean up = p instanceof @UWM@;
  if (!up && !(p instanceof @CWM@)) return;
  @PKG@.MmSess s = (@PKG@.MmSess) SESS.get(pr.getUuid());
  if (s == null || s.pr != pr) return;
  // 0.3.16: the player's world changed (World.addPlayer sets it before the join's ClearWorldMap + burst): one boundary marker first
  java.util.UUID wu = pr.getWorldUuid();
  if (wu != null && !wu.equals(s.tapW)) { s.tapW = wu; s.q.add(wu); }
  int qa = s.qn.incrementAndGet();
  int qg = GQN.incrementAndGet();
  if (qa > @QMAX@ || qg > @GQMAX@) { s.qn.decrementAndGet(); GQN.decrementAndGet(); s.dropped.incrementAndGet(); return; }
  if (up) {
    @UWM@ u = (@UWM@) p;
    @MCH@[] cs = u.chunks;
    int n = cs == null ? 0 : cs.length;
    boolean over = false;
    if (n > 0) {
      int ca = s.qc.addAndGet(n);
      int cg = GQC.addAndGet(n);
      over = ca > @QCHUNKS@ || cg > @GQCHUNKS@;
    }
    if (over) {
      s.qc.addAndGet(-n);
      GQC.addAndGet(-n);
      // past the image bound: the chunk keys only (the pieces are not held; the engine cache serves them) + the markers as they came
      int m = 0;
      for (int i = 0; i < n; i++) if (cs[i] != null && cs[i].image != null) m = m + 1;
      long[] ks = new long[m + 1];
      int j = 0;
      boolean real = false;
      for (int i = 0; i < n && j < m; i++) {
        if (cs[i] != null && cs[i].image != null) {
          ks[j] = key(cs[i].chunkX, cs[i].chunkZ);
          j = j + 1;
          if (!real && !@PKG@.MmPng.empty(cs[i].image)) real = true;
        }
      }
      ks[m] = real ? 1L : 0L;
      s.q.add(ks);
      s.keysOnly.incrementAndGet();
      if (u.addedMarkers != null || u.removedMarkers != null) {
        int ma = s.qn.incrementAndGet();
        int mg = GQN.incrementAndGet();
        if (ma > @QMAX@ || mg > @GQMAX@) { s.qn.decrementAndGet(); GQN.decrementAndGet(); s.dropped.incrementAndGet(); return; }
        s.q.add(new @UWM@((@MCH@[]) null, u.addedMarkers, u.removedMarkers));
      }
      return;
    }
  }
  s.q.add(p);
}""")
