# 0.3.31 MENU PATTERN (kit 1.7): the Minimap / Dynamic Seasons settings are drawn INSIDE the Settings > HUD hub page's scroll list #SkyySetL
# (SettingsPage.build draws the hub page shell first): no frame / title bar of their own (the sub-tab row names the widget; 38 px less),
# no back button (rows 1 + 2 and All widgets lead away); every row, id, payload and Reset unchanged
def _in_hub_page(src, root):
    import re as _re
    out, n = [], {"root": 0, "bar": 0, "orn": 0, "body": 0, "back": 0, "bind": 0}
    for ln in src.split("\n"):
        m = _re.match(r'  b\.appendInline\(\(String\) null, "Group #%s \{ Anchor: \(Width: (\d+), Height: (\d+)\); \}"\);\Z' % root, ln)
        if m:
            out.append('  b.appendInline("#SkyySetL", "Group #%s { Anchor: (Width: %s, Height: %d); }");' % (root, m.group(1), int(m.group(2)) - 38))
            n["root"] += 1
        elif ('"Group #%sBar {' % root) in ln:
            n["bar"] += 1
        elif ln.startswith('  b.appendInline("#%s", "Group { Anchor: (Width: 236, Height: 11, Bottom: -6);' % root):
            n["orn"] += 1
        elif ln.startswith('  b.appendInline("#%s", "Group #%sBody { Anchor: (Top: 38); LayoutMode: Top; Padding: (Full: 17); Background:' % (root, root)):
            out.append('  b.appendInline("#%s", "Group #%sBody { LayoutMode: Top; Padding: (Full: 17); }");' % (root, root))
            n["body"] += 1
        elif ('TextButton #%sBack {' % root) in ln:
            n["back"] += 1
        elif ('"#%sBack", ' % root) in ln:
            n["bind"] += 1
        else:
            out.append(ln)
    assert all(v == 1 for v in n.values()), "0.3.31 %s in the hub page: %s" % (root, n)
    res = "\n".join(out)
    assert ("<" + " Back") not in res and "ContainerPatch" not in res and "(String) null" not in res
    return res


MMUI_JAVA = _in_hub_page(MMUI_JAVA, "SkyyMmS")
