# nearest free canvas cell to `target` (squared grid distance, lowest index on ties) - handles are never dropped
page.addMethod(CtNewMethod.make(f"""
public int freeCellNear(int target) {{
  if (target < 0) target = 0;
  if (target > 575) target = 575;
  if (this.cellWidget[target] == null) return target;
  int tc = target % 32; int tr = target / 32;
  int best = -1; int bestD = 2147483647;
  for (int c = 0; c < 576; c++) {{
    if (this.cellWidget[c] != null) continue;
    int dc = c % 32 - tc; int dr = c / 32 - tr;
    int d = dc * dc + dr * dr;
    if (d < bestD) {{ bestD = d; best = c; }}
  }}
  return best;
}}""", page))
