# the visible widget covering most of a canvas cell (later widgets are drawn on top and win ties)
page.addMethod(CtNewMethod.make(f"""
public String widgetAtCell(java.util.Map m, String[] ids, int cell) {{
  int x0 = (cell % 32) * 60; int y0 = (cell / 32) * 60;
  String best = null; int bestA = 0;
  for (int i = 0; i < ids.length; i++) {{
    {PKG}.WLayout l = ({PKG}.WLayout) m.get(ids[i]);
    if (l == null || !l.en) continue;
    int h = heightOf(ids[i], l);
    int w = widthOf(ids[i], l);
    int[] p = {PKG}.Widgets.screenPosWH(l, w, h);
    int ox = Math.min(p[0] + w, x0 + 60) - Math.max(p[0], x0);
    int oy = Math.min(p[1] + h, y0 + 60) - Math.max(p[1], y0);
    if (ox <= 0 || oy <= 0) continue;
    if (ox * oy >= bestA) {{ bestA = ox * oy; best = ids[i]; }}
  }}
  return best;
}}""", page))
# previews at TRUE positions (screen x 2/3), drawn BEFORE the grid = behind the invisible handles (proven visible on 0.3.3)
