page.addMethod(CtNewMethod.make(f"""
public void handleDataEvent({REF} ref, {ST} st, String data) {{
  try {{
    if (data == null) return;
    java.util.UUID u = this.playerRef.getUuid();
    java.util.Map m = {PKG}.LayoutStore.get(u);
    String[] ids = {PKG}.Widgets.edIds();
    if (data.indexOf("\\"drop\\"") >= 0 || data.indexOf("Dropped") >= 0) {{
      int from = jsonInt(data, "SourceSlotId");
      int to = jsonInt(data, "SlotIndex");
      if (from < 0 || to < 0 || from >= 576 || to >= 576 || this.cellWidget == null) {{ {PKG}.LayoutStore.debug("drop payload: " + data); return; }}
      String wid = this.cellWidget[from];
      if (wid == null) return;
      {PKG}.WLayout l = ({PKG}.WLayout) m.get(wid);
      if (l == null) return;
      if (to == from) {{ this.sel = wid; this.info = ""; rebuild(); return; }}
      {PKG}.Widgets.moveByCellsWH(l, from, to, widthOf(wid, l), heightOf(wid, l));
      String other = this.cellWidget[to];
      this.sel = wid;
      this.info = (other != null && !other.equals(wid)) ? "moved " + {PKG}.Widgets.label(wid) + " onto " + {PKG}.Widgets.label(other) + " - nudge with the arrows to separate them" : "moved " + {PKG}.Widgets.label(wid);
      {PKG}.LayoutStore.save(u); plugin.rebuildFor(u); rebuild(); return;
    }}
    if (data.indexOf("\\"slot\\"") >= 0) {{
      int idx = jsonInt(data, "SlotIndex");
      if (idx < 0 || idx >= 576 || this.cellWidget == null) {{ {PKG}.LayoutStore.debug("slot payload: " + data); return; }}
      String hit = this.cellWidget[idx];
      if (hit == null) hit = widgetAtCell(m, ids, idx);
      if (hit != null && !hit.equals(this.sel)) {{ this.sel = hit; this.info = ""; rebuild(); }}
      return;
    }}
    if (data.indexOf("\\"dragcancel\\"") >= 0) return;
    if (data.indexOf("\\"setup\\"") >= 0) {{ openSetup(); return; }}
    if (data.indexOf("\\"widgets\\"") >= 0) {{
      {PLA} player = ({PLA}) st.getComponent(ref, {PLA}.getComponentType());
      if (player != null) player.getPageManager().openCustomPage(ref, st, new {PKG}.HudHubPage(this.playerRef, this.plugin));   // 0.3.31: the hub page list
      return;
    }}
    for (int i = 0; i < ids.length; i++) {{
      if (data.indexOf("sel:" + ids[i] + "\\"") >= 0) {{
        {PKG}.WLayout l = ({PKG}.WLayout) m.get(ids[i]);
        if (l != null && l.en && !ids[i].equals(this.sel)) {{ this.sel = ids[i]; this.info = ""; rebuild(); }}
        return;
      }}
    }}
    for (int i = 0; i < ids.length; i++) {{
      if (data.indexOf("show:" + ids[i] + "\\"") >= 0) {{
        {PKG}.WLayout l = ({PKG}.WLayout) m.get(ids[i]);
        if (l != null) {{ l.en = true; {PKG}.Widgets.clampToScreen(l); this.sel = ids[i]; {PKG}.LayoutStore.save(u); plugin.rebuildFor(u); }}
        rebuild(); return;
      }}
    }}
    if (this.sel == null) return;
    {PKG}.WLayout l = ({PKG}.WLayout) m.get(this.sel);
    if (l == null) return;
    if (data.indexOf("act:Cog\\"") >= 0) {{
      {PLA} player = ({PLA}) st.getComponent(ref, {PLA}.getComponentType());
      if (player != null) player.getPageManager().openCustomPage(ref, st, new {PKG}.SettingsPage(this.playerRef, this.plugin, this.sel));
      return;
    }}
    if (data.indexOf("act:Step\\"") >= 0) {{ nextStep(); rebuild(); return; }}
    int step = getStep();
    String a = l.anchor;
    boolean rightEdge = a.equals("tr") || a.equals("r") || a.equals("br");
    boolean bottomEdge = a.equals("bl") || a.equals("b") || a.equals("br");
    if (data.indexOf("act:Hide\\"") >= 0) {{ l.en = false; this.info = "hid " + {PKG}.Widgets.label(this.sel) + " - click it in the Hidden row to bring it back"; this.sel = null; }}
    else if (data.indexOf("act:Lt\\"") >= 0) l.dx += rightEdge ? step : -step;
    else if (data.indexOf("act:Rt\\"") >= 0) l.dx += rightEdge ? -step : step;
    else if (data.indexOf("act:Up\\"") >= 0) l.dy += bottomEdge ? step : -step;
    else if (data.indexOf("act:Dn\\"") >= 0) l.dy += bottomEdge ? -step : step;
    else if (data.indexOf("act:Sm\\"") >= 0) l.scale -= "Minimap".equals(this.sel) ? 25 : 10;
    else if (data.indexOf("act:Sp\\"") >= 0) l.scale += "Minimap".equals(this.sel) ? 25 : 10;
    else {{ {PKG}.LayoutStore.debug("unknown editor payload: " + data); return; }}
    if (l.scale < 50) l.scale = 50;
    if (l.scale > 200) l.scale = 200;
    {PKG}.Widgets.clampToScreen(l);
    {PKG}.LayoutStore.save(u); plugin.rebuildFor(u); rebuild();
  }} catch (Throwable t) {{ {PKG}.LayoutStore.debug("editor event failed: " + t); }}
}}""", page))

