sett.addMethod(CtNewMethod.make(f"""
public String previewText() {{
  if ("Skills".equals(this.wid) || "Combat".equals(this.wid) || "Abilities".equals(this.wid) || "Quest".equals(this.wid) || "Stacks".equals(this.wid)) {{
    try {{
      {PKG}.WLayout sl = ({PKG}.WLayout) {PKG}.LayoutStore.get(this.playerRef.getUuid()).get(this.wid);
      String[] sm = {PKG}.Widgets.viewModel(this.wid, this.playerRef, sl);
      if (sm != null && sm[1] != null && sm[1].length() > 0) return sm[1];
    }} catch (Throwable x) {{ }}
    return {PKG}.Widgets.label(this.wid);
  }}
  long join = System.currentTimeMillis();
  try {{ {PKG}.HudMain hm = ({PKG}.HudMain) this.plugin.huds.get(this.playerRef.getUuid()); if (hm != null) join = hm.joinMs; }} catch (Throwable t) {{ }}
  String t = null;
  try {{ t = {PKG}.Widgets.text(this.wid, this.playerRef, join); }} catch (Throwable x) {{ t = null; }}
  if (t == null || t.length() == 0 || t.equals("?")) t = {PKG}.Widgets.label(this.wid);
  return t;
}}""", sett))
