sett.addMethod(CtNewMethod.make(f"""
public void handleDataEvent({REF} ref, {ST} st, String data) {{
  try {{
    if (data == null) return;
    java.util.UUID u = this.playerRef.getUuid();
    // 0.3.31: a hub click FIRST (row 1 hub:h:<id>, row 2 hub:<tab>, the X); this hub / the HUD tab = the widget list
    String hr = null;
    try {{ hr = {PKG}.HubBar.route(this.playerRef, data, "settings", "hud"); }} catch (Throwable t) {{ hr = null; }}
    if (hr != null) {{
      if (hr.equals("close")) {{ close(); return; }}
      if (hr.equals("self")) {{ openList(ref, st); return; }}
      if (hr.equals("back") || hr.equals("bridge") || hr.equals("command")) {{ hubAck(); return; }}
      this.playerRef.sendMessage({MSG}.raw("[SkyyHud] That tab could not open right now - try again."));
      return;
    }}
    String sa = {PKG}.HubBar.jsonStr(data, "a");
    if (sa.equals("wlist")) {{ openList(ref, st); return; }}
    if (sa.equals("hudedit")) {{ openEditor(ref, st); return; }}
    if ("Seasons".equals(this.wid)) {{
      int dr = {PKG}.DsUi.click(this.playerRef, data);
      if (dr == 1) {{ openList(ref, st); return; }}     // 0.3.31: (no back button any more; an old payload = the list)
      if (dr == 2) {{ plugin.rebuildFor(u); rebuild(); }}
      return;
    }}
    if ("Minimap".equals(this.wid)) {{
      int mr = {PKG}.MmUi.click(this.playerRef, data);
      if (mr == 1) {{ openList(ref, st); return; }}     // 0.3.31: (no back button any more; an old payload = the list)
      if (mr == 2) {{ plugin.rebuildFor(u); rebuild(); }}
      return;
    }}
    {PKG}.WLayout l = ({PKG}.WLayout) {PKG}.LayoutStore.get(u).get(this.wid);
    if (l == null) return;
    if (data.indexOf("\\"back\\"") >= 0) {{ openList(ref, st); return; }}     // 0.3.31: an old back payload = the list
    if (data.indexOf("\\"opton\\"") >= 0) {{ l.opt = true; l.optH = "Abilities".equals(this.wid); }}   // 0.3.32: optH = chose Hide (Abilities)
    else if (data.indexOf("\\"optoff\\"") >= 0) {{ l.opt = false; l.optH = false; }}
    else if (data.indexOf("\\"on\\"") >= 0) l.en = true;
    else if (data.indexOf("\\"off\\"") >= 0) l.en = false;
    else if (data.indexOf("\\"bgon\\"") >= 0) l.bg = true;
    else if (data.indexOf("\\"bgoff\\"") >= 0) l.bg = false;
    else if (data.indexOf("\\"sz:") >= 0) {{ int v = jsonAfter(data, "sz:"); if (v >= 50 && v <= 200) l.scale = v; }}
    else if (data.indexOf("\\"an:") >= 0) {{ int p = data.indexOf("\\"an:") + 4; int q = data.indexOf('\\"', p); String a = data.substring(p, q); if ({PKG}.WLayout.validAnchor(a)) {PKG}.Widgets.snapTo(l, a); }}
    else if (data.indexOf("\\"bon\\"") >= 0) l.bold = true;
    else if (data.indexOf("\\"boff\\"") >= 0) l.bold = false;
    else if (data.indexOf("\\"ion\\"") >= 0) l.ital = true;
    else if (data.indexOf("\\"ioff\\"") >= 0) l.ital = false;
    else if (data.indexOf("\\"gon\\"") >= 0) l.glow = true;
    else if (data.indexOf("\\"goff\\"") >= 0) l.glow = false;
    else if (data.indexOf("\\"rstyle\\"") >= 0) {{ l.col = "def"; l.bold = true; l.ital = false; l.glow = false; l.gcol = "def"; l.ocol = "def"; }}
    else if (data.indexOf("\\"ocol:") >= 0) {{ if (!"Combat".equals(this.wid)) return; String c = strAfter(data, "\\"ocol:"); int ci = {PKG}.WLayout.palIdx(c); if (ci >= 0 && ci < {PKG}.WLayout.TEXT_N) l.ocol = c; else return; }}
    else if (data.indexOf("\\"col:") >= 0) {{ String c = strAfter(data, "\\"col:"); int ci = {PKG}.WLayout.palIdx(c); if (ci >= 0 && ci < {PKG}.WLayout.TEXT_N) l.col = c; }}
    else if (data.indexOf("\\"gcol:") >= 0) {{ String c = strAfter(data, "\\"gcol:"); if ({PKG}.WLayout.palIdx(c) >= 0) {{ l.gcol = c; l.glow = true; }} }}
    else if (data.indexOf("\\"ln:") >= 0) {{
      int k = jsonAfter(data, "ln:");
      if (l.ldef < 0 || k < 0 || k >= {PKG}.WLayout.LINE_N) return;
      int nm = l.lines ^ (1 << k);
      if ((nm & {PKG}.Widgets.skillsVis({PKG}.Widgets.bridge())) == 0) return;
      l.lines = nm;
    }}
    else if (data.indexOf("\\"lnall\\"") >= 0) {{ if (l.ldef < 0) return; l.lines = l.lines | {PKG}.WLayout.LINES_ALL; }}
    else if (data.indexOf("\\"lndef\\"") >= 0) {{ if (l.ldef < 0) return; l.lines = {PKG}.Widgets.startLines(this.wid); }}
    else return;
    {PKG}.Widgets.clampToScreen(l);
    {PKG}.LayoutStore.save(u); plugin.rebuildFor(u); rebuild();
  }} catch (Throwable t) {{ {PKG}.LayoutStore.debug("settings event failed: " + t); }}
}}""", sett))


