# 0.3.25 (Skyy: "the item tracker on the side is confusing. it says mine 64 stone and 18/50."): PROGRESS cards = a running count in the text
# - kind collection ("Cobblestone 32 / 50"), a quest task-progress card ("Mine 64 stone"; not "Done: ..." / "Reward: ..."), or any text
# with "<digit> / <digit>". They show no "xN" merge counter and carry a prefix saying what they are; every other card is unchanged.
FXM(feed, """
public static boolean hasRatio(String t) {
  if (t == null) return false;
  int n = t.length();
  for (int i = 0; i < n; i++) {
    if (t.charAt(i) != '/') continue;
    int a = i - 1;
    while (a >= 0 && t.charAt(a) == ' ') a--;
    int z = i + 1;
    while (z < n && t.charAt(z) == ' ') z++;
    if (a >= 0 && z < n && Character.isDigit(t.charAt(a)) && Character.isDigit(t.charAt(z))) return true;
  }
  return false;
}""")
