cmd.addMethod(CtNewMethod.make(f"""
public static void act({PKG}.SkyyHudPlugin plugin, {PR} pr, String action, String rest) {{
  java.util.UUID u = pr.getUuid();
  if (action.equals("export")) {{
    pr.sendMessage({MSG}.raw("[SkyyHud] layout code: " + {PKG}.LayoutStore.export(u)));
    return;
  }}
  if (action.equals("import")) {{
    if (rest == null || rest.trim().length() == 0) {{ pr.sendMessage({MSG}.raw("[SkyyHud] usage: /skyyhud import <code>")); return; }}
    int n = {PKG}.LayoutStore.importCode(u, rest);
    if (n > 0) plugin.rebuildFor(u);
    pr.sendMessage({MSG}.raw("[SkyyHud] imported " + n + " widget layout(s)"));
    return;
  }}
  if (action.equals("reset")) {{
    {PKG}.LayoutStore.reset(u);
    plugin.rebuildFor(u);
    pr.sendMessage({MSG}.raw({PKG}.HudCfg.hasDefault() ? "[SkyyHud] layout reset to this server's default layout" : "[SkyyHud] layout reset to defaults"));
    return;
  }}
  if (action.equals("preview")) {{
    pr.sendMessage({MSG}.raw("[SkyyHud] since 0.3.4 the editor always shows live previews behind invisible drag handles - nothing to switch"));
    return;
  }}
  if (action.equals("profile")) {{
    String r = rest == null ? "" : rest.trim();
    if (r.length() >= 2 && ((r.charAt(0) == '"' && r.charAt(r.length() - 1) == '"') || (r.charAt(0) == '\\'' && r.charAt(r.length() - 1) == '\\''))) r = r.substring(1, r.length() - 1).trim();
    String sub = r; String name = "";
    int sp = r.indexOf(' ');
    if (sp > 0) {{ sub = r.substring(0, sp); name = r.substring(sp + 1).trim(); }}
    sub = sub.toLowerCase();
    if (sub.equals("list")) {{ String lst2 = {PKG}.LayoutStore.profileList(u); pr.sendMessage({MSG}.raw("[SkyyHud] profiles: " + (lst2.length() == 0 ? "(none)" : lst2))); return; }}
    if (sub.equals("save")) {{ pr.sendMessage({MSG}.raw({PKG}.LayoutStore.profileSave(u, name) ? "[SkyyHud] saved profile " + {PKG}.LayoutStore.cleanName(name) : "[SkyyHud] usage: /skyyhud profile save <name>")); return; }}
    if (sub.equals("load")) {{ int n = {PKG}.LayoutStore.profileLoad(u, name); if (n > 0) plugin.rebuildFor(u); pr.sendMessage({MSG}.raw(n >= 0 ? "[SkyyHud] loaded profile " + {PKG}.LayoutStore.cleanName(name) : "[SkyyHud] no such profile")); return; }}
    if (sub.equals("delete")) {{ pr.sendMessage({MSG}.raw({PKG}.LayoutStore.profileDelete(u, name) ? "[SkyyHud] deleted profile" : "[SkyyHud] no such profile")); return; }}
    pr.sendMessage({MSG}.raw("[SkyyHud] usage: /skyyhud profile save|load|delete <name> | list")); return;
  }}
  pr.sendMessage({MSG}.raw("[SkyyHud] unknown action '" + action + "' (export | import <code> | reset | profile ...)"));
}}""", cmd))


